SELECT SUM(100) OVER (PARTITION BY "deptno", 5000 ORDER BY 5000 RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS "col1", SUM(100) OVER (PARTITION BY 5000 ORDER BY "deptno" RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS "col2", SUM(5000) OVER (PARTITION BY "deptno" ORDER BY 5000 RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS "col3"
FROM "emp"
WHERE "sal" = 5000;
